    "staghorn_coral": { id: "staghorn_coral", name: "Staghorn Coral", scientific: "Acropora cervicornis", rarity: "Common", tag: "Corals & Anemones", typicalRegion: "Warm Shallow Waters", description: "Formulates massive branching structures mimicking deer antlers." },
    "elkhorn_coral": { id: "elkhorn_coral", name: "Elkhorn Coral", scientific: "Acropora palmata", rarity: "Common", tag: "Corals & Anemones", typicalRegion: "Inshore Reef Flats", description: "Provides vital structure with thick, flat, moose-horn branches." },
