    "torch_coral": { id: "torch_coral", name: "Torch Coral", scientific: "Euphyllia glabrescens", rarity: "Common", tag: "Corals & Anemones", typicalRegion: "Lagoon Reef Tops", description: "Long fleshy tentacles tipped in glowing green or pink dots." },
