    // ==================== EEL ====================
    "giant_moray": { id: "giant_moray", name: "Giant Moray", scientific: "Gymnothorax javanicus", rarity: "Common", tag: "Eel", typicalRegion: "Indo-Pacific Reef Crevices", description: "The largest moray on Indo-Pacific reefs, often seen with cleaner shrimp." },
    "yellow_margin_moray": { id: "yellow_margin_moray", name: "Yellow-margin Moray", scientific: "Gymnothorax flavimarginatus", rarity: "Common", tag: "Eel", typicalRegion: "Rocky & Coral Reef Crevices", description: "Recognized by the pale yellow trim edging its dorsal fin." },
    "honeycomb_moray": { id: "honeycomb_moray", name: "Honeycomb Moray", scientific: "Gymnothorax favagineus", rarity: "Epic", tag: "Eel", typicalRegion: "Coral Rubble Slopes", description: "Bold black honeycomb-patterned skin over a pale body." },
    "snowflake_moray": { id: "snowflake_moray", name: "Snowflake Moray", scientific: "Echidna nebulosa", rarity: "Common", tag: "Eel", typicalRegion: "Shallow Reef Flats & Tide Pools", description: "Blunt, molar-like teeth built for crushing crab and shrimp shells." },
    "white_eyed_moray": { id: "white_eyed_moray", name: "White-eyed Moray", scientific: "Siderea thyrsoidea", rarity: "Epic", tag: "Eel", typicalRegion: "Sandy Reef Slopes", description: "Pale grey moray easily identified by its striking white-ringed eyes." },
    "fimbriated_moray": { id: "fimbriated_moray", name: "Fimbriated Moray", scientific: "Gymnothorax fimbriatus", rarity: "Common", tag: "Eel", typicalRegion: "Coral Reef Crevices", description: "Dark-spotted moray commonly seen peeking out from reef holes by day." },
    "undulated_moray": { id: "undulated_moray", name: "Undulated Moray", scientific: "Gymnothorax undulatus", rarity: "Common", tag: "Eel", typicalRegion: "Shallow Reef Flats", description: "Wavy dark markings across a yellow-green body, active at night." },
